package com.example.starter.certificate.dto;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.time.Instant;

/**
 * 发布合格证声明请求。validFrom/validTo 为 ISO-8601 UTC 时间，区间按左闭右开解释。
 */
public record PublishDeclarationRequest(
        @NotBlank(message = "commandKey 不能为空") String commandKey,
        @NotBlank(message = "declarationKey 不能为空") String declarationKey,
        @NotNull(message = "version 不能为空") @Min(value = 1, message = "version 必须 >= 1") Integer version,
        @NotBlank(message = "materialCode 不能为空") String materialCode,
        @NotBlank(message = "batchNoPrefix 不能为空") String batchNoPrefix,
        @NotNull(message = "priority 不能为空") Integer priority,
        @NotNull(message = "validFrom 不能为空") Instant validFrom,
        @NotNull(message = "validTo 不能为空") Instant validTo
) {
}

package com.example.starter.certificate.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 撤回合格证声明请求。
 */
public record WithdrawDeclarationRequest(
        @NotBlank(message = "commandKey 不能为空") String commandKey,
        @NotBlank(message = "reason 不能为空") String reason
) {
}

package com.example.starter.certificate.dto;

import java.time.Instant;

/**
 * 合格证声明版本响应。validFrom/validTo 为 UTC instant，区间左闭右开；
 * withdrawnAt/withdrawnBy/withdrawReason 为 null 表示未撤回。
 */
public record DeclarationResponse(
        String declarationKey,
        int version,
        String materialCode,
        String batchNoPrefix,
        int priority,
        Instant validFrom,
        Instant validTo,
        String status,
        String publishedBy,
        Instant createdAt,
        Instant withdrawnAt,
        String withdrawnBy,
        String withdrawReason
) {
}

package com.example.starter.certificate.dto;

import java.util.List;

/**
 * 声明明细响应：同一声明键的全部版本，按版本号升序稳定排序。
 */
public record DeclarationDetailResponse(
        String declarationKey,
        List<DeclarationResponse> versions
) {
}

package com.example.starter.certificate.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 批量绑定合格证请求：1～10 条绑定；任一失效或不匹配则整次回滚，不产生半成品。
 */
public record BindCertificatesRequest(
        @NotBlank(message = "commandKey 不能为空") String commandKey,
        @NotNull(message = "bindings 不能为空")
        @Size(min = 1, max = 10, message = "bindings 必须包含 1～10 条绑定")
        List<@Valid BindingSpec> bindings
) {
    /**
     * 单条绑定规格：批次 + 目标声明版本。
     */
    public record BindingSpec(
            @NotBlank(message = "batchKey 不能为空") String batchKey,
            @NotBlank(message = "declarationKey 不能为空") String declarationKey,
            @NotNull(message = "declarationVersion 不能为空")
            @Min(value = 1, message = "declarationVersion 必须 >= 1") Integer declarationVersion
    ) {
    }
}

package com.example.starter.certificate.dto;

import java.time.Instant;

/**
 * 批次合格证绑定响应。boundAt 为 UTC instant。
 */
public record BindingResponse(
        String batchKey,
        String declarationKey,
        int declarationVersion,
        String matchedPrefix,
        String boundBy,
        Instant boundAt
) {
}

package com.example.starter.certificate.dto;

import java.util.List;

/**
 * 批量绑定响应：boundCount 为实际绑定条数，bindings 按请求顺序返回。
 */
public record BindCertificatesResponse(
        int boundCount,
        List<BindingResponse> bindings
) {
}

