        JsonNode body = objectMapper.readTree(ok.getResponse().getContentAsString());
        assertEquals(2, body.path("boundCount").asInt());
        assertEquals(2, jdbc.queryForObject("SELECT COUNT(*) FROM batch_certificate_binding",
                Integer.class));
    }

